package com.harvestflow.registration.service.impl;
import com.harvestflow.registration.entity.DocumentType; import com.harvestflow.registration.exception.DocumentValidationException; import com.harvestflow.registration.service.DocumentStorageService; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.IOException; import java.nio.file.*; import java.util.Set; import java.util.UUID;
@Service public class LocalDocumentStorageService implements DocumentStorageService { private static final Set<String> TYPES=Set.of("image/jpeg","image/png","application/pdf"); private static final long MAX=5L*1024*1024; @Value("${harvestflow.registration.document-storage-path:uploads/registration-docs}") String base;
 public String storeDocument(UUID id,DocumentType type,MultipartFile file){if(file==null||file.isEmpty())throw new DocumentValidationException(type+" is required");if(file.getSize()>MAX)throw new DocumentValidationException(type+" exceeds 5MB");if(file.getContentType()==null||!TYPES.contains(file.getContentType()))throw new DocumentValidationException(type+" must be JPG, PNG or PDF");try{Path dir=Paths.get(base,id.toString());Files.createDirectories(dir);String ext=file.getContentType().equals("application/pdf")?".pdf":file.getContentType().equals("image/png")?".png":".jpg";Path p=dir.resolve(type.name().toLowerCase()+"_"+UUID.randomUUID()+ext);file.transferTo(p);return p.toString();}catch(IOException e){throw new DocumentValidationException("Failed to store "+type);}}
}
